@pytest.mark.parametrize("auth_type", ["valid", "invalid", "missing"])
def test_store_order_auth(api_client, auth_type, test_data):
    """
    Test /store/order endpoint with different authentication scenarios.
    """
    endpoint = "/store/order"
    headers = {"Content-Type": "application/json"}
    payload = {
        "id": test_data['orderId'],
        "petId": test_data['petId'],
        "quantity": 1
    }

    if auth_type == "valid":
        response = api_client.post(endpoint, headers=headers, json=payload)
        assert response.status_code == 200, "Expected 200 for valid authentication"

    elif auth_type == "invalid":
        headers['Authorization'] = "Bearer invalid_token"
        response = api_client.post(endpoint, headers=headers, json=payload)
        assert response.status_code == 401, "Expected 401 for invalid authentication"

    elif auth_type == "missing":
        response = api_client.post(endpoint, headers=headers, json=payload)
        assert response.status_code == 401, "Expected 401 for missing authentication"

